# Look at requests between 02:50 and 03:18, especially anything related to batch/jobs/users that may have spiked
awk '$1 ~ /T0[2-3]:/ { 
  split($1, a, "T"); 
  sub(/:.*/, "", a[2]);
  min = substr(a[2], length(a[2])-1);
  if ($1 >= "2026-01-18T02:50" && $1 <= "2026-01-18T03:18") print $0
}' /tmp/agent_opt_scratch/baseline_32k__logtriage_04_pool_exhaustion__08/work/app.log | grep -v 'INFO.*200' | head -30

